using System.Net;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;
using WireMock.RequestBuilders;
using WireMock.ResponseBuilders;
using WireMock.Server;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly WireMockServer provider = WireMockServer.Start();
    private readonly HttpClient client;
    private readonly HttpPaymentGateway sut;

    public HttpPaymentGatewayTests()
    {
        client = new HttpClient { BaseAddress = new Uri(provider.Url!) };
        sut = new HttpPaymentGateway(client);
    }

    private void Provider(int status, string? body = null)
    {
        var response = Response.Create().WithStatusCode(status);
        if (body is not null) response = response.WithHeader("Content-Type", "application/json").WithBody(body);
        provider.Given(Request.Create().WithPath("/v1/authorizations").UsingPost()).RespondWith(response);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        sut.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

    [Fact]
    public async Task The_request_is_a_json_post_with_reference_amount_and_currency()
    {
        Provider(200, """{"status":"approved"}""");

        await Authorize();

        var entry = Assert.Single(provider.LogEntries);
        Assert.Equal("POST", entry.RequestMessage!.Method);
        Assert.Equal("/v1/authorizations", entry.RequestMessage.Path);
        Assert.StartsWith("application/json", entry.RequestMessage.Headers!["Content-Type"][0]);
        using var json = JsonDocument.Parse(entry.RequestMessage.Body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Provider(200, """{"status":"approved"}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Provider(200, """{"status":"declined"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        Provider(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_payment_required_refusal_is_a_decline_not_an_error()
    {
        Provider(402, """{"error":"card_refused"}""");

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_raised_and_never_read_as_approval(int status)
    {
        Provider(status, """{"status":"approved"}""");

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_approved_is_never_treated_as_approved(string body)
    {
        Provider(200, body);

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_malformed_answer_is_raised()
    {
        Provider(200, "<html>oops</html>");

        await Assert.ThrowsAsync<JsonException>(Authorize);
    }

    public void Dispose()
    {
        client.Dispose();
        provider.Stop();
        provider.Dispose();
    }
}
EOF
